    // --- Range comparison helpers --------------------------------
    // All helpers return true if a <= b.

    // Unsigned / bool: little-endian word comparison from MSB to LSB.
    static bool reg_cmp_le(const word_t* a, const word_t* b, uint8_t n) {
        for (int8_t _i = (int8_t)(n - 1u); _i >= 0; --_i) {
            if (a[_i] < b[_i]) {
                return true;
            }
            if (a[_i] > b[_i]) {
                return false;
            }
        }
        return true;
    }

    // Signed: locate the actual sign bit (last_word_bits gives MSB position),
    // then compare as positive/negative before falling back to unsigned word order.
    static bool reg_cmp_le_signed(const word_t* a, const word_t* b, uint8_t n, uint8_t last_word_bits) {
        // last_word_bits==0 → last word fully used; sign bit is the MSB of word_t.
        const uint8_t sign_shift = (last_word_bits == 0u)
            ? (uint8_t)(sizeof(word_t) * 8u - 1u)
            : (uint8_t)(last_word_bits - 1u);
        const word_t sign_bit = word_t(1u) << sign_shift;
        const bool a_neg = (a[n - 1u] & sign_bit) != 0u;
        const bool b_neg = (b[n - 1u] & sign_bit) != 0u;
        if (a_neg != b_neg) {
            return a_neg;
        }
        return reg_cmp_le(a, b, n);
    }

    // Float: reconstruct and compare as IEEE 754 single.
    static bool reg_cmp_le_float(const word_t* a, const word_t* b) {
        float fa, fb;
        memcpy(&fa, a, sizeof(float));
        memcpy(&fb, b, sizeof(float));
        return fa <= fb;
    }

    // Double: reconstruct and compare as IEEE 754 double.
    static bool reg_cmp_le_double(const word_t* a, const word_t* b) {
        double da, db;
        memcpy(&da, a, sizeof(double));
        memcpy(&db, b, sizeof(double));
        return da <= db;
    }

    // --- reg_read ------------------------------------------------
    RegStatus reg_read(uint16_t address, word_t* out, uint16_t count) {
        if (address >= REG_TABLE_SIZE)
            return RegStatus::BAD_ADDRESS_OUT_OF_RANGE;

        const RegAddrSlot& slot = reg_table[address];

        if (!slot.reg)
            return RegStatus::BAD_ADDRESS;

        const RegInfo&     info = *slot.reg;

        if (info.access == RegAccess::WRITE)
            return RegStatus::BAD_ACCESS_WRITE_ONLY;
        if (slot.word_idx + count > info.valid_words)
            return RegStatus::REGISTER_OVERFLOW;

        if (info.words_per_reg == 1) {
            out[0] = info.storage[0];
            return RegStatus::OK;
        }
        else if (slot.word_idx == 0 && count == info.valid_words) {
            // Full register read — copy directly from storage under critical section.
            INTRO_REG_ENTER_CRITICAL();
            memcpy(out, info.storage, info.valid_words * sizeof(word_t));
            INTRO_REG_EXIT_CRITICAL();
            return RegStatus::OK;
        }
        else {
            // Partial read — hardware atomic (no buffer) or snapshot path.
            if (info.read_buf == nullptr) {
                // No software buffer: hardware atomicity covers this register width.
                INTRO_REG_ENTER_CRITICAL();
                memcpy(out, &info.storage[slot.word_idx], count * sizeof(word_t));
                INTRO_REG_EXIT_CRITICAL();
                return RegStatus::OK;
            }
            if (slot.word_idx == 0) {
                INTRO_REG_ENTER_CRITICAL();
                memcpy(info.read_buf, info.storage, info.valid_words * sizeof(word_t));
                INTRO_REG_EXIT_CRITICAL();
            }
            memcpy(out, &info.read_buf[slot.word_idx], count * sizeof(word_t));
            if (slot.word_idx == 0) {
                return RegStatus::OK_ATOMIC_UPDATED;
            }
            return RegStatus::OK_ATOMIC_BUFFERED;
        }

        return RegStatus::BAD_RETURN;
    }

    // --- reg_write -----------------------------------------------
    RegStatus reg_write(uint16_t address, const word_t* data, uint16_t count) {
        if (address >= REG_TABLE_SIZE)
            return RegStatus::BAD_ADDRESS_OUT_OF_RANGE;

        const RegAddrSlot& slot = reg_table[address];

        if (!slot.reg)
            return RegStatus::BAD_ADDRESS;

        const RegInfo&     info = *slot.reg;

        if (info.access == RegAccess::READ)
            return RegStatus::BAD_ACCESS_READ_ONLY;
        if (slot.word_idx + count > info.valid_words)
            return RegStatus::REGISTER_OVERFLOW;

        // Check that the last valid word has no bits set above the register width.
        if (info.last_word_bits != 0) {
            uint8_t last_idx = info.valid_words - 1u;
            if (slot.word_idx + count > last_idx) {
                if (data[last_idx - slot.word_idx] >> info.last_word_bits) {
                    return RegStatus::BITS_ABOVE_WIDTH;
                }
            }
        }

        // Range check: dispatch to the correct comparator for the register's type.
        if (info.min_val) {
            bool _in_range;
            switch (info.type) {
                case RegType::SIGNED:
                    _in_range = reg_cmp_le_signed(info.min_val, data, info.valid_words, info.last_word_bits)
                             && reg_cmp_le_signed(data, info.max_val, info.valid_words, info.last_word_bits);
                    break;
                case RegType::FLOAT:
                    _in_range = reg_cmp_le_float(info.min_val, data)
                             && reg_cmp_le_float(data, info.max_val);
                    break;
                case RegType::DOUBLE:
                    _in_range = reg_cmp_le_double(info.min_val, data)
                             && reg_cmp_le_double(data, info.max_val);
                    break;
                default:
                    _in_range = reg_cmp_le(info.min_val, data, info.valid_words)
                             && reg_cmp_le(data, info.max_val, info.valid_words);
                    break;
            }
            if (!_in_range) {
                return RegStatus::OUT_OF_RANGE;
            }
        }

        if (info.words_per_reg == 1) {
            info.storage[0] = data[0];
            return RegStatus::OK;
        }
        else if (slot.word_idx == 0 && count == info.valid_words) {
            // Full register write — commit directly to storage under critical section.
            INTRO_REG_ENTER_CRITICAL();
            memcpy(info.storage, data, info.valid_words * sizeof(word_t));
            INTRO_REG_EXIT_CRITICAL();
            return RegStatus::OK;
        }
        else {
            // Partial write — hardware atomic (no buffer) or staged path.
            if (info.write_buf == nullptr) {
                // No software buffer: write directly; hardware atomicity covers this register width.
                INTRO_REG_ENTER_CRITICAL();
                memcpy(&info.storage[slot.word_idx], data, count * sizeof(word_t));
                INTRO_REG_EXIT_CRITICAL();
                return RegStatus::OK;
            }
            memcpy(&info.write_buf[slot.word_idx], data, count * sizeof(word_t));
            if (slot.word_idx + count == info.valid_words) {
                INTRO_REG_ENTER_CRITICAL();
                memcpy(info.storage, info.write_buf, info.valid_words * sizeof(word_t));
                INTRO_REG_EXIT_CRITICAL();
            }
        }

        return RegStatus::BAD_RETURN;
    }

    // --- reg_reset -----------------------------------------------
    void reg_reset() {
        memset(&regs, 0, sizeof(regs));
        for (uint16_t i = 0; i < REG_INFO_COUNT; ++i) {
            const RegInfo& info = reg_info[i];
            // Restore declared defaults after zeroing.
            if (info.default_val) {
                memcpy(info.storage, info.default_val, info.valid_words * sizeof(word_t));
            }
            if (info.read_buf) {
                memset(info.read_buf,  0, info.words_per_reg * sizeof(word_t));
            }
            if (info.write_buf) {
                memset(info.write_buf, 0, info.words_per_reg * sizeof(word_t));
            }
        }
    }

